result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "db.py", "content": """"Shared helpers: connection, phase-A/B schemas, exact money conversions.

Money invariant: price_cents INTEGER is the legacy storage; price_decimal TEXT
is the canonical "exact decimal string" (e.g. 1999 <-> "19.99"). Conversions
are pure integer/string math so they are exact — never float.
"""

import os
import sqlite3

DB_PATH = os.environ.get("DB_PATH", "shop.db")

# PRAGMA user_version lifecycle:
#   0 = phase A (price_cents only)
#   1 = phase B (expanded: price_decimal added)
#   2 = phase C (contracted: price_cents dropped)
SCHEMA_VERSIONS = {"A": 0, "B": 1, "C": 2}

BOOKMARK_TABLE_SQL = """
CREATE TABLE IF NOT EXISTS migration_bookmark (
    name    TEXT PRIMARY KEY,
    last_id INTEGER NOT NULL
)
"""


def db_path() -> str:
    return os.environ.get("DB_PATH", DB_PATH)


def connect() -> sqlite3.Connection:
    conn = sqlite3.connect(db_path())
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys=ON")
    return conn


def init_phase_a(conn: sqlite3.Connection) -> None:
    """Phase A schema: single integer cents column."""
    conn.executescript(
        """
        CREATE TABLE IF NOT EXISTS products (
            id          INTEGER PRIMARY KEY,
            name        TEXT NOT NULL,
            price_cents INTEGER NOT NULL
        );
        """
    )
    _set_version(conn, SCHEMA_VERSIONS["A"])
    conn.commit()


def columns(conn: sqlite3.Connection, table: str = "products") -> set[str]:
    return {row["name"] for row in conn.execute(f"PRAGMA table_info({table})")}


def get_version(conn: sqlite3.Connection) -> int:
    return int(conn.execute("PRAGMA user_version").fetchone()[0])


def _set_version(conn: sqlite3.Connection, version: int) -> None:
    conn.execute(f"PRAGMA user_version={int(version)}")


def cents_to_decimal_str(cents: int) -> str:
    """Exact conversion. 1999 -> '19.99', -250 -> '-2.50', 700 -> '7.00'."""
    cents = int(cents)
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def parse_price(price: str) -> tuple[int, str]:
    """Parse a user-supplied decimal string into (cents, canonical decimal str).

    Accepts at most 2 fractional digits; rejects anything else so that both
    storage formats stay exactly consistent.
    """
    from decimal import Decimal, InvalidOperation

    try:
        d = Decimal(str(price).strip())
    except InvalidOperation:
        raise ValueError(f"invalid price: {price!r}")
    if not d.is_finite():
        raise ValueError(f"invalid price: {price!r}")
    exponent = d.as_tuple().exponent
    if isinstance(exponent, str) or exponent < -2:
        raise ValueError(f"price supports at most 2 decimal places: {price!r}")
    scaled = d.scaleb(2)
    if scaled != scaled.to_integral_value():
        raise ValueError(f"price supports at most 2 decimal places: {price!r}")
    cents = int(scaled)
    return cents, cents_to_decimal_str(cents)


def seed_products(conn: sqlite3.Connection, n: int = 500) -> None:
    """Seed n products deterministically (phase A column only)."""
    rows = [
        (f"product-{i:04d}", 100 + i * 13 % 90000) for i in range(1, n + 1)
    ]
    conn.executemany(
        "INSERT INTO products (name, price_cents) VALUES (?, ?)", rows
    )
    conn.commit()
