result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "app.py", "content": """"FastAPI app over the SQLite products table.

Environment flags (read per-request so tests can flip them live):

  PRICE_READ_SOURCE = old | new   which column GETs read from
                                    old -> price_cents (converted to string)
                                    new -> price_decimal (canonical string)
  DUAL_WRITE       = 1 | 0        when expanding writes, keep both columns
                                  in sync (app-level dual-write)

Writes always go to every column that exists in the table, gated by
DUAL_WRITE only while the new column exists but backfill/dual-write has not
been enabled yet.
"""

import os
import sqlite3
from typing import Optional

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

from db import (
    cents_to_decimal_str,
    columns,
    connect,
    parse_price,
)

app = FastAPI(title="expand-contract rehearsal")


class ProductIn(BaseModel):
    name: str
    price: str


class ProductPatch(BaseModel):
    name: Optional[str] = None
    price: Optional[str] = None


def _read_source() -> str:
    return os.environ.get("PRICE_READ_SOURCE", "old").strip().lower()


def _dual_write() -> bool:
    return os.environ.get("DUAL_WRITE", "0").strip() == "1"


def _row_to_product(row: sqlite3.Row) -> dict:
    cols = columns_of_row(row)
    source = _read_source()
    if source == "new":
        if "price_decimal" not in cols:
            raise HTTPException(
                status_code=500,
                detail="PRICE_READ_SOURCE=new but price_decimal column missing",
            )
        price = row["price_decimal"]
        if price is None:  # pre-backfill row: fall back to old column
            price = cents_to_decimal_str(row["price_cents"])
    else:
        if "price_cents" in cols and row["price_cents"] is not None:
            price = cents_to_decimal_str(row["price_cents"])
        elif row["price_decimal"] is not None:
            price = row["price_decimal"]
        else:
            raise HTTPException(status_code=500, detail="no price stored")
    return {"id": row["id"], "name": row["name"], "price": price}


def columns_of_row(row: sqlite3.Row) -> set[str]:
    return set(row.keys())


def _fetch_one(conn: sqlite3.Connection, product_id: int):
    row = conn.execute(
        "SELECT * FROM products WHERE id = ?", (product_id,)
    ).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="product not found")
    return row


@app.get("/health")
def health():
    conn = connect()
    try:
        version = int(conn.execute("PRAGMA user_version").fetchone()[0])
    finally:
        conn.close()
    return {
        "status": "ok",
        "schema_version": version,
        "read_source": _read_source(),
        "dual_write": _dual_write(),
    }


@app.get("/products")
def list_products():
    conn = connect()
    try:
        rows = conn.execute(
            "SELECT * FROM products ORDER BY id"
        ).fetchall()
        return [_row_to_product(r) for r in rows]
    finally:
        conn.close()


@app.get("/products/{product_id}")
def get_product(product_id: int):
    conn = connect()
    try:
        return _row_to_product(_fetch_one(conn, product_id))
    finally:
        conn.close()


@app.post("/products", status_code=201)
def create_product(body: ProductIn):
    cents, dec = _parse_or_400(body.price)
    conn = connect()
    try:
        cols = columns(conn)
        cur = conn.execute(
            "INSERT INTO products (name, price_cents) VALUES (?, ?)",
            (body.name, cents),
        )
        pid = cur.lastrowid
        if "price_decimal" in cols:
            if not _dual_write():
                # Column exists but dual-write disabled: revert insert.
                conn.rollback()
                raise HTTPException(
                    status_code=409,
                    detail="dual-write disabled while expanded schema active",
                )
            conn.execute(
                "UPDATE products SET price_decimal=? WHERE id=?", (dec, pid)
            )
        conn.commit()
        return _row_to_product(_fetch_one(conn, pid))
    finally:
        conn.close()


@app.put("/products/{product_id}")
def update_product(product_id: int, body: ProductPatch):
    conn = connect()
    try:
        _fetch_one(conn, product_id)
        sets, params = [], []
        if body.name is not None:
            sets.append("name=?")
            params.append(body.name)
        if body.price is not None:
            cents, dec = _parse_or_400(body.price)
            cols = columns(conn)
            if "price_cents" in cols:
                sets.append("price_cents=?")
                params.append(cents)
            if "price_decimal" in cols:
                if not _dual_write():
                    raise HTTPException(
                        status_code=409,
                        detail="dual-write disabled while expanded schema active",
                    )
                sets.append("price_decimal=?")
                params.append(dec)
            if not sets:
                raise HTTPException(status_code=500, detail="no price column")
        if not sets:
            raise HTTPException(status_code=400, detail="nothing to update")
        params.append(product_id)
        conn.execute(f"UPDATE products SET {', '.join(sets)} WHERE id=?", params)
        conn.commit()
        return _row_to_product(_fetch_one(conn, product_id))
    finally:
        conn.close()


def _parse_or_400(price: str) -> tuple[int, str]:
    try:
        return parse_price(price)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc))


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="127.0.0.1", port=int(os.environ.get("PORT", "8000")))
"})
